package com.kynsoft.report.infrastructure.entity;
import com.kynsoft.report.domain.dto.EstadoConteoFisico; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.LocalDateTime; import java.util.UUID;
@Getter @Setter @Entity @Table(name="conteo_fisico_almacen") public class ConteoFisicoAlmacen { @Id private UUID id; @Column(name="finca_id",nullable=false) private UUID fincaId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="almacen_id",nullable=false) private Almacen almacen; @Column(nullable=false,unique=true,length=40) private String numero; @Enumerated(EnumType.STRING) @Column(nullable=false,length=15) private EstadoConteoFisico estado; @Column(name="fecha_apertura",nullable=false) private LocalDateTime fechaApertura; @Column(name="fecha_cierre") private LocalDateTime fechaCierre; @Column(name="responsable_conteo",nullable=false,length=150) private String responsableConteo; @Column(name="verificado_por",length=150) private String verificadoPor; @Column(name="autorizado_por",length=150) private String autorizadoPor; @Column(name="observaciones_apertura",length=1000) private String observacionesApertura; @Column(name="observaciones_cierre",length=1000) private String observacionesCierre; @Column(name="numero_ajuste",length=40) private String numeroAjuste; @Column(name="usuario_id") private UUID usuarioId; }
